files.content:
/* Content fades in and rises into place as it scrolls into view. --on-energy-rise sets the
   distance, --on-energy-reveal-delay pushes the start later (staggers siblings). */
@supports (animation-timeline: view()) {
  .on-energy-reveal {
    animation: on-energy-reveal-in linear both;
    animation-timeline: view();
    animation-range:
      entry calc(var(--on-energy-reveal-delay, 0) * 1%)
      cover calc(25% + var(--on-energy-reveal-delay, 0) * 1%);
  }
}

@keyframes on-energy-reveal-in {
  from { opacity: 0; transform: translateY(var(--on-energy-rise, 0px)); }
  to { opacity: 1; transform: none; }
}

@media (prefers-reduced-motion: reduce) {
  .on-energy-reveal { animation: none !important; }
}

import type { CSSProperties, ElementType, ReactNode } from "react";
import { cn } from "@foundry/foundry-utils";
import "./on-energy-reveal.css";

export interface OnEnergyRevealProps {
  /** what fades in */
  children: ReactNode;
  /** the element to render (default "div") */
  as?: ElementType;
  /** how far it rises while fading in, in px (0 = fade only) */
  rise?: number;
  /** pushes the start later, in % of the scroll range: staggers siblings */
  delay?: number;
  className?: string;
}

/**
 * Wraps content that fades in (and optionally rises) as it scrolls into view, scrubbed with
 * the scroll by a CSS view timeline. Static HTML shows the content in place.
 */
export function OnEnergyReveal({ children, as: Tag = "div", rise = 0, delay = 0, className }: OnEnergyRevealProps) {
  return (
    <Tag
      className={cn("on-energy-reveal", className)}
      style={{ "--on-energy-rise": `${rise}px`, "--on-energy-reveal-delay": delay } as CSSProperties}
    >
      {children}
    </Tag>
  );
}
